import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.Cooo9kuv.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"win系统可以安全删除的文件夹-以清理释放系统空间","日期":"2026-04-09T00:00:00.000Z","修改日期":"2026-04-09T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["win系统问题"],"标签":["win系统清理","win系统维护","安全删除文件夹"]},"headers":[{"level":3,"title":"可以删除的目录：","slug":"可以删除的目录","link":"#可以删除的目录","children":[]},{"level":3,"title":"浏览器缓存文件夹","slug":"浏览器缓存文件夹","link":"#浏览器缓存文件夹","children":[]},{"level":3,"title":"临时文件夹（Temp 文件夹）","slug":"临时文件夹-temp-文件夹","link":"#临时文件夹-temp-文件夹","children":[]},{"level":3,"title":"预读文件夹（Prefetch）","slug":"预读文件夹-prefetch","link":"#预读文件夹-prefetch","children":[]},{"level":3,"title":"旧的系统备份文件夹","slug":"旧的系统备份文件夹","link":"#旧的系统备份文件夹","children":[]},{"level":3,"title":"系统日志文件夹","slug":"系统日志文件夹","link":"#系统日志文件夹","children":[]},{"level":3,"title":"Windows Update 下载缓存文件夹","slug":"windows-update-下载缓存文件夹","link":"#windows-update-下载缓存文件夹","children":[]},{"level":3,"title":"系统错误内存转储文件","slug":"系统错误内存转储文件","link":"#系统错误内存转储文件","children":[]}],"relativePath":"md/win系统问题/win系统可以安全删除的文件夹-以清理释放系统空间.md","filePath":"md/win系统问题/win系统可以安全删除的文件夹-以清理释放系统空间.md"}'),l={name:"md/win系统问题/win系统可以安全删除的文件夹-以清理释放系统空间.md"};function n(o,e,s,d,h,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<p>只需要删除以下列出的文件夹内的文件即可，主文件夹没必要，也不必删除，更不建议删除。<br> 只需要复制下方路径，你的电脑名称替换为实际电脑名即可。</p><h3 id="可以删除的目录" tabindex="-1">可以删除的目录： <a class="header-anchor" href="#可以删除的目录" aria-label="Permalink to &quot;可以删除的目录：&quot;">​</a></h3><p>C:\\Windows\\Prefetch<br> C:\\Users\\你的电脑名称\\AppData\\Roaming\\Microsoft\\Windows\\Recent<br> C:\\Users\\你的电脑名称\\AppData\\Roaming</p><h3 id="浏览器缓存文件夹" tabindex="-1">浏览器缓存文件夹 <a class="header-anchor" href="#浏览器缓存文件夹" aria-label="Permalink to &quot;浏览器缓存文件夹&quot;">​</a></h3><p>Chrome：C:\\Users\\你的用户名\\AppData\\Local\\Google\\Chrome\\User Data\\Default\\Cache<br> Edge：C:\\Users\\你的用户名\\AppData\\Local\\Microsoft\\Edge\\User Data\\Default\\Cache</p><p>[yk_WeChatFans]</p><h3 id="临时文件夹-temp-文件夹" tabindex="-1">临时文件夹（Temp 文件夹） <a class="header-anchor" href="#临时文件夹-temp-文件夹" aria-label="Permalink to &quot;临时文件夹（Temp 文件夹）&quot;">​</a></h3><p>C:\\Windows\\Temp<br> C:\\Users&lt;用户名&gt;\\AppData\\Local\\Temp</p><h3 id="预读文件夹-prefetch" tabindex="-1">预读文件夹（Prefetch） <a class="header-anchor" href="#预读文件夹-prefetch" aria-label="Permalink to &quot;预读文件夹（Prefetch）&quot;">​</a></h3><p>C:\\Windows\\Prefetch<br> 预读取文件夹存储了程序的启动数据，可以加速程序启动。删除它们不会影响系统，但重新启动程序时会重新生成。</p><h3 id="旧的系统备份文件夹" tabindex="-1">旧的系统备份文件夹 <a class="header-anchor" href="#旧的系统备份文件夹" aria-label="Permalink to &quot;旧的系统备份文件夹&quot;">​</a></h3><p>C:\\Windows.old</p><h3 id="系统日志文件夹" tabindex="-1">系统日志文件夹 <a class="header-anchor" href="#系统日志文件夹" aria-label="Permalink to &quot;系统日志文件夹&quot;">​</a></h3><p>C:\\Windows\\Logs</p><h3 id="windows-update-下载缓存文件夹" tabindex="-1">Windows Update 下载缓存文件夹 <a class="header-anchor" href="#windows-update-下载缓存文件夹" aria-label="Permalink to &quot;Windows Update 下载缓存文件夹&quot;">​</a></h3><p>C:\\Windows\\SoftwareDistribution\\Download<br> 这是 Windows 更新下载的缓存文件夹。删除其中内容不会影响已安装的更新，但下次检查更新时，系统可能会重新下载更新文件。清空该文件夹可释放一定空间。</p><h3 id="系统错误内存转储文件" tabindex="-1">系统错误内存转储文件 <a class="header-anchor" href="#系统错误内存转储文件" aria-label="Permalink to &quot;系统错误内存转储文件&quot;">​</a></h3><p>C:\\Windows\\Minidump<br> C:\\Windows\\memory.dmp<br> 这些是系统崩溃时生成的调试文件。对普通用户没有用处，可以安全删除。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/548.html" target="_blank" rel="noreferrer">https://www.softbangong.com/548.html</a></p>',20)])])}const m=a(l,[["render",n]]);export{_ as __pageData,m as default};
